"""Journal : (1) HA1 devient « non tranchée » (appariement incorrect) et on préinscrit HA1b, le montage apparié ; (2) décision D8 et hypothèses HB1 à HB7 du bloc B, préinscrites avant tout calcul. Idempotent."""
import sys, pathlib
sys.path.insert(0, str(pathlib.Path(__file__).resolve().parents[1] / "src"))
import tp2_journal as J
last = [e for e in J.entries() if e["id"] == "HA1"][-1]
if last["version"] == 3 - 1 + 0 and last["statut"] == "confirmée":
    J.add("HA1", "hypothese", last["titre"], last["texte"], justification="Remise en cause par l'étudiant (2026-11-07) : le test de Wilcoxon apparié comparait P0 et P2 pli par pli, alors que ces deux protocoles n'évaluent pas les mêmes logs ; la différence de plis peut influer sur les scores et les écarts. L'appariement n'était donc pas justifié.",
          statut="non tranchée", preuve=last["preuve"], note="Le verdict « confirmée » de la version 2 est conservé dans l'historique. Rejouée de deux façons : (a) réanalyse des mêmes données avec un test NON apparié (Mann-Whitney) ; (b) HA1b, montage apparié sur les mêmes logs de test.")
if not J.exists("HA1b"):
    J.add("HA1b", "hypothese", "Effet pur de la fuite, sur les mêmes logs de test",
          "Montage apparié : pour chaque pli de groupes (répétition r, pli k), le test est une moitié tirée au hasard des logs du pli (T_b). Condition G : entraînement = logs des autres plis (aucun log des gabarits de test). Condition H : entraînement = G plus l'autre moitié des logs du pli (T_a), donc des logs des mêmes gabarits que T_b. Les deux conditions sont évaluées sur les MÊMES logs T_b. Hypothèse : pour chacun des six modèles, le macro-F1 du palier A est plus élevé en H qu'en G d'au moins 0,20 (Wilcoxon apparié sur 25 plis, Holm p < 0,05).",
          justification="Seule la présence de logs du même gabarit dans l'entraînement change : c'est l'effet pur de la fuite, mesuré sans que les plis ni les logs de test diffèrent. Le seuil de 0,20 est fixé par prudence, très en dessous de l'écart de 0,48 à 0,55 observé entre P0 et P2.", statut="préinscrite",
          note="Écrit le 2026-11-07 avant tout calcul de ce montage.")
if not J.exists("D8"):
    J.add("D8", "decision", "Bloc B : classifieurs comparés et protocole",
          "Protocole P2 (5 plis de groupes × 5 répétitions), SIEVE_00, 400 logs au plus par gabarit, baseline = SVM sur mots. Plats : SVM mots, régression logistique. Hiérarchique local p(famille) × p(classe | famille). Voisinage et prototypes : kNN (k = 5 et 15), centroïde, k-means par classe (k = 3 et 10 prototypes), gabarits-prototypes (notre proposition F3), Naive Bayes. Clustering de types variés, dans l'espace SVD de dimension 100 du TF-IDF : par classe (k-means, mélange gaussien, classification hiérarchique ascendante de Ward) et global non supervisé avec étiquette majoritaire (k-means à K = 60 et 150, Birch, DBSCAN, HDBSCAN ; les points de bruit sont comptés comme rejetés).",
          justification="Demandé par l'étudiant (2026-11-07) : comparer la classification hiérarchique à d'autres approches de classification, dont le clustering et ses différents types, toutes avec tests statistiques. DBSCAN et HDBSCAN rejettent naturellement les points isolés : ils annoncent le bloc C. Spectral écarté : coût quadratique en mémoire sur ce volume.", preuve="scripts/v3_blockB.py")
HB = [
 ("HB1", "La hiérarchie n'améliore pas le macro-F1 des classes", "Sous P2, le macro-F1 des classes (palier A) du modèle hiérarchique ne diffère pas significativement du modèle plat de même famille (régression logistique) : Wilcoxon, Holm p >= 0,05, ou |écart| < 0,03.", "Notebook v1 : gain « non démontré », signe qui change entre validation et test."),
 ("HB2", "La hiérarchie améliore le F1 des familles", "Le macro-F1 des familles (famille déduite de la classe prédite pour le plat) est plus élevé avec la hiérarchie d'au moins 0,03 (Wilcoxon, Holm p < 0,05).", "La tête famille est entraînée directement sur la famille, plus facile (0,67 contre 0,46 au notebook v1)."),
 ("HB3", "La hiérarchie réduit la gravité des erreurs", "La distance moyenne d'erreur dans l'arbre (0 même classe, 1 même famille, 2 autre famille) est plus petite avec la hiérarchie (Wilcoxon, Holm p < 0,05).", "Une classe prédite cohérente avec la famille prédite rapproche les erreurs ; notebook v1 : 0,83 contre 0,86 pour TF-IDF."),
 ("HB4", "Plusieurs prototypes valent mieux qu'un", "Le k-means par classe à 10 prototypes dépasse le centroïde unique (Wilcoxon, Holm p < 0,05).", "Une classe contient plusieurs gabarits : un seul centre les moyenne et se place entre eux."),
 ("HB5", "Les gabarits-prototypes (F3) dépassent le centroïde mais pas le SVM", "Sous P2, gabarits-prototypes meilleur que le centroïde (Holm p < 0,05) et inférieur au SVM sur mots d'au moins 0,03.", "Les gabarits sont les groupes naturels, mais un nouveau gabarit n'a pas de prototype proche : on s'attend à mieux que le centroïde sans égaler un classifieur discriminant."),
 ("HB6", "Le clustering non supervisé n'atteint pas le SVM", "Aucun des clustering globaux non supervisés (k-means global, Birch, DBSCAN, HDBSCAN) n'atteint le SVM sur mots : écart d'au moins 0,05, Holm p < 0,05, pour chacun.", "Sans les étiquettes, les groupes se forment sur les gabarits et non sur les classes ; l'étiquette majoritaire est une approximation."),
 ("HB7", "Un clustering par classe rivalise avec le kNN", "Au moins une méthode de clustering supervisé par classe (k-means, mélange gaussien, Ward) ou les gabarits-prototypes est indiscernable du kNN (Friedman puis Nemenyi : différence de rang moyen inférieure à la différence critique).", "Ces méthodes utilisent les mêmes distances que le kNN avec un résumé des classes."),
]
for i, t, tx, j in HB:
    if not J.exists(i): J.add(i, "hypothese", t, tx, justification=j, statut="préinscrite", note="Écrit le 2026-11-07 avant tout calcul du bloc B (hormis les modèles kNN, centroïde et Naive Bayes déjà vus au bloc A, sous le même protocole).")
print(J.render())
